import { Theme } from '@astryxdesign/core/theme';
import { neutralTheme } from '@astryxdesign/theme-neutral/built';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { createRouter, RouterProvider } from '@tanstack/react-router';
import { StrictMode } from 'react';
import { createRoot } from 'react-dom/client';
import '@astryxdesign/core/reset.css';
import '@astryxdesign/core/astryx.css';
import '@astryxdesign/theme-neutral/theme.css';

import './index.css';
// eslint-disable-next-line n/no-missing-import -- generated by the TanStack Router vite plugin at build time
import { routeTree } from './routeTree.gen';
import { telemetry } from './telemetry.js';

// Start browser telemetry first: spans attach to this process from the first fetch.
// `telemetry` is undefined outside the browser, so this no-ops there.
telemetry?.();

const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      // The dashboard polls; retries are the poll itself.
      retry: false,
      staleTime: 0,
    },
  },
});

const router = createRouter({
  context: { queryClient },
  routeTree,
});

declare module '@tanstack/react-router' {
  interface Register {
    router: typeof router;
  }
}

const rootElement = document.querySelector('#root');
if (!rootElement) throw new Error('missing #root element');

createRoot(rootElement).render(
  <StrictMode>
    <Theme theme={neutralTheme}>
      <QueryClientProvider client={queryClient}>
        <RouterProvider router={router} />
      </QueryClientProvider>
    </Theme>
  </StrictMode>,
);
